UPDATE dev_terminal_activation SET status='CONSUMED',consumed_device_id=#{deviceId},consumed_at=#{at},
  record_version=record_version+1 WHERE activation_id=#{activationId} AND status='ISSUED'
  AND record_version=#{expectedVersion} AND expires_at>#{at}

mapper.select:
SELECT  FROM pos_sync_device
WHERE tenant_id=#{tenantId} AND store_id=#{storeId}
ORDER BY activated_at DESC,device_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT request_sha256 requestSha256,aggregate_id aggregateId,result_code resultCode,
  CAST(result_json AS CHAR) resultJson,result_sha256 resultSha256 FROM dev_terminal_command_result
WHERE tenant_id=#{tenantId} AND command_type=#{commandType} AND idempotency_key=#{idempotencyKey}
